from pathlib import Path

p = Path('app.js')
s = p.read_text()
s = s.replace("type:'مادة خام'", "type:'مواد خام'")
s = s.replace("{id:2,sku:'RAW-002',name:'حجر زركون أبيض',type:'مواد خام'", "{id:2,sku:'RAW-002',name:'حجر زركون أبيض',type:'مواد إنتاج'")
seed_end = "production:[{id:1,no:'PR-2026-0018',product:'خاتم فضة كلاسيكي',qty:50,status:'مكتمل',date:'2026/09/30'},{id:2,no:'PR-2026-0019',product:'سوار فضة ناعم',qty:30,status:'قيد التنفيذ',date:'2026/10/01'},{id:3,no:'PR-2026-0020',product:'خاتم فضة كلاسيكي',qty:100,status:'مسودة',date:'2026/10/02'}]};"
seed_new = "production:[{id:1,no:'PR-2026-0018',product:'خاتم فضة كلاسيكي',qty:50,status:'مكتمل',date:'2026/09/30'},{id:2,no:'PR-2026-0019',product:'سوار فضة ناعم',qty:30,status:'قيد التنفيذ',date:'2026/10/01'},{id:3,no:'PR-2026-0020',product:'خاتم فضة كلاسيكي',qty:100,status:'مسودة',date:'2026/10/02'}],stockReceipts:[{id:1,no:'GR-2026-0014',source:'مورد المعادن المتحدة',warehouse:'مخزن تحت التشغيل',lines:3,total:42850,date:'2026/09/30',status:'مرحل'},{id:2,no:'GR-2026-0013',source:'توريد افتتاحي',warehouse:'مخزن تحت التشغيل',lines:2,total:18600,date:'2026/09/25',status:'مسودة'}],cashboxes:[{id:1,name:'الصندوق الرئيسي',type:'رئيسي / تجميعي',parent:null,balance:86450,children:[{name:'صندوق المبيعات',balance:52800},{name:'صندوق المصروفات',balance:21650},{name:'صندوق العهدة',balance:12000}]}]};"
if seed_end not in s:
    raise SystemExit('seed end not found')
s = s.replace(seed_end, seed_new)
s = s.replace("const titles={dashboard:'لوحة التحكم',vouchers:'السندات'", "const titles={dashboard:'لوحة التحكم',vouchers:'السندات',stockReceipts:'أوامر التوريد المخزني',cashboxes:'الصناديق',")
old_inventory = "function inventory(){return tablePage('inventory',db.items,['SKU','الصنف','النوع','الوحدة','الكمية المتاحة','متوسط التكلفة',''],rs=>rs.map(x=>`<tr><td><b>${x.sku}</b></td><td>${esc(x.name)}</td><td>${x.type}</td><td>${x.unit}</td><td class=\"amount\">${x.stock.toLocaleString('ar-SA')}</td><td>${money(x.cost)}</td><td><button class=\"link-btn\" data-edit=\"item\" data-id=\"${x.id}\">تعديل</button></td></tr>`).join(''),'إضافة صنف','item')}"
new_inventory = """function inventory(){return tablePage('inventory',db.items,['SKU','الصنف','التصنيف','مكان التخزين','الوحدة','الكمية المتاحة','متوسط التكلفة',''],rs=>rs.map(x=>`<tr><td><b>${x.sku}</b></td><td>${esc(x.name)}</td><td>${x.type}</td><td>${x.type==='صنف مركب'?'مخزون الإنتاج التام':'مخزون تحت التشغيل'}</td><td>${x.unit}</td><td class=\"amount\">${x.stock.toLocaleString('ar-SA')}</td><td>${money(x.cost)}</td><td><button class=\"link-btn\" data-edit=\"item\" data-id=\"${x.id}\">تعديل</button></td></tr>`).join(''),'إضافة صنف','item')}\nfunction stockReceipts(){return tablePage('stockReceipts',db.stockReceipts,['رقم الأمر','المورد / المصدر','المخزن المستلم','عدد البنود','الإجمالي','التاريخ','الحالة'],rs=>rs.map(x=>`<tr><td><b>${x.no}</b></td><td>${esc(x.source)}</td><td>${x.warehouse}</td><td>${x.lines}</td><td class=\"amount\">${money(x.total)}</td><td>${x.date}</td><td>${status(x.status)}</td></tr>`).join(''),'أمر توريد جديد','stockReceipt')}\nfunction cashboxes(){return layout('cashboxes',`<div class=\"card section-card\"><div class=\"section-title\"><div><h2>هيكل الصندوق</h2><p style=\"color:var(--muted);font-size:10px\">الصندوق الرئيسي تجميعي، والحركات تسجل على الصناديق الفرعية</p></div><button class=\"primary-btn\" data-action=\"cashbox\">＋ صندوق فرعي</button></div>${db.cashboxes.map(x=>`<div class=\"list-row\"><div><b>▾ ${x.name}</b><small style=\"display:block;color:var(--muted);font-size:10px\">${x.type} · الرصيد التجميعي</small>${x.children.map(c=>`<div style=\"padding:10px 28px 0;color:#526177;font-size:11px\">└ ${c.name}<strong style=\"float:left\">${money(c.balance)}</strong></div>`).join('')}</div><strong>${money(x.balance)}</strong></div>`).join('')}</div>`)}"""
if old_inventory not in s:
    raise SystemExit('inventory block not found')
s = s.replace(old_inventory, new_inventory)
s = s.replace("page==='customers'?customers():page==='inventory'?inventory():page==='vouchers'?vouchers():page==='invoices'?invoices():page==='production'?production():page==='accounts'?accounts():page==='reports'?reports():settings();", "page==='customers'?customers():page==='inventory'?inventory():page==='stockReceipts'?stockReceipts():page==='cashboxes'?cashboxes():page==='vouchers'?vouchers():page==='invoices'?invoices():page==='production'?production():page==='accounts'?accounts():page==='reports'?reports():settings();")
s = s.replace("type==='production'?'أمر إنتاج':'إضافة حساب'", "type==='production'?'أمر إنتاج':type==='stockReceipt'?'أمر توريد مخزني':type==='cashbox'?'إضافة صندوق فرعي':'إضافة حساب'")
modal_marker = "else form=`<div class=\"field\"><label>رمز الحساب</label>"
modal_insert = """else if(type==='stockReceipt')form=`<div class=\"field\"><label>المورد / المصدر</label><input id=\"f-source\" placeholder=\"مثال: مورد المعادن المتحدة\"></div><div class=\"field\"><label>المخزن المستلم</label><select id=\"f-warehouse\"><option>مخزن تحت التشغيل</option></select></div><div class=\"field full\"><label>الصنف</label><select id=\"f-item\">${db.items.filter(x=>x.type!=='صنف مركب').map(x=>`<option value=\"${x.id}\">${x.name} — ${x.type}</option>`).join('')}</select></div><div class=\"field\"><label>الكمية</label><input id=\"f-qty\" type=\"number\" min=\"0.001\" value=\"1\"></div><div class=\"field\"><label>تكلفة الوحدة</label><input id=\"f-cost\" type=\"number\" min=\"0.01\" value=\"0\"></div><div class=\"field full\"><label>ملاحظات</label><textarea id=\"f-desc\"></textarea></div>`;else if(type==='cashbox')form=`<div class=\"field full\"><label>اسم الصندوق الفرعي</label><input id=\"f-cashbox-name\" placeholder=\"مثال: صندوق المبيعات\"></div><div class=\"field\"><label>العملة</label><select><option>ريال سعودي (SAR)</option></select></div><div class=\"field\"><label>الرصيد الافتتاحي</label><input id=\"f-cashbox-balance\" type=\"number\" value=\"0\"></div>`+modal_marker"""
if modal_marker not in s:
    raise SystemExit('modal marker not found')
s = s.replace(modal_marker, modal_insert)
submit_marker = "else if(type==='production'){db.production.unshift({id:Date.now(),no:'PR-2026-'+String(db.production.length+21).padStart(4,'0'),product:el('#f-product').value,qty:+el('#f-qty').value,date:today,status:'مسودة'})}save();"
submit_new = """else if(type==='production'){db.production.unshift({id:Date.now(),no:'PR-2026-'+String(db.production.length+21).padStart(4,'0'),product:el('#f-product').value,qty:+el('#f-qty').value,date:today,status:'مسودة'})}else if(type==='stockReceipt'){let qty=+el('#f-qty').value,cost=+el('#f-cost').value;if(qty<=0||cost<=0){toast('أدخل كمية وتكلفة صحيحتين');return}let item=db.items.find(x=>x.id==+el('#f-item').value);db.stockReceipts.unshift({id:Date.now(),no:'GR-2026-'+String(db.stockReceipts.length+15).padStart(4,'0'),source:el('#f-source').value||'توريد داخلي',warehouse:el('#f-warehouse').value,lines:1,total:qty*cost,date:today,status:'مسودة'});item.stock+=qty;item.cost=((item.cost||0)+cost)/2}else if(type==='cashbox'){let name=el('#f-cashbox-name').value||'صندوق فرعي جديد',balance=+el('#f-cashbox-balance').value;db.cashboxes[0].children.push({name,balance});db.cashboxes[0].balance+=balance}else form=""" 
if submit_marker not in s:
    raise SystemExit('submit marker not found')
s = s.replace(submit_marker, submit_new)
p.write_text(s)

p = Path('index.html')
s = p.read_text()
s = s.replace('<button class="nav-item" data-page="vouchers"><span>↔</span> السندات</button>', '<button class="nav-item" data-page="vouchers"><span>↔</span> السندات</button>\n        <button class="nav-item" data-page="stockReceipts"><span>⇩</span> أوامر التوريد المخزني</button>')
s = s.replace('<button class="nav-item" data-page="inventory"><span>▦</span> المخزون والأصناف</button>', '<button class="nav-item" data-page="inventory"><span>▦</span> المخزون والأصناف</button>\n        <button class="nav-item" data-page="cashboxes"><span>▣</span> الصناديق الرئيسية والفرعية</button>')
p.write_text(s)
